const menu = doc.querySelector('#nav-dialog');
const opener = doc.querySelector('#nav-open');
let navOpening = false;
let previousOverflow = '';
let navLocked = false;
let destination = null;
if (menu && opener && typeof menu.showModal === 'function') {
  opener.addEventListener('click', async () => {
    if (menu.open || navOpening) return;
    navOpening = true;
    await Promise.all([...doc.querySelectorAll('dialog[open]')].filter(other => other !== menu).map(other => new Promise(resolve => {
      other.addEventListener('close', resolve, { once: true }); other.close();
    })));
    previousOverflow = doc.body.style.overflow;
    doc.body.style.overflow = 'hidden'; navLocked = true;
    try { menu.showModal(); } catch { doc.body.style.overflow = previousOverflow; navLocked = false; }
    navOpening = false;
  });
  doc.querySelector('#nav-close')?.addEventListener('click', () => menu.close());
  menu.querySelectorAll('a[href^="#"]').forEach(link => link.addEventListener('click', () => {
    destination = doc.getElementById(link.hash.slice(1));
    menu.close();
  }));
  menu.addEventListener('close', () => {
    if (navLocked) doc.body.style.overflow = previousOverflow;
    navLocked = false;
    if (destination) {
      const target = destination.querySelector('h2') ?? destination;
      target.setAttribute('tabindex', '-1'); target.focus({ preventScroll: true }); destination = null;
    } else opener.focus({ preventScroll: true });
  });
}

// Encode free-text origins; the destination stays the user-selected address.
const routeForm = doc.querySelector('#map-route-form');
routeForm?.addEventListener('submit', event => {
  event.preventDefault();
  const origin = doc.querySelector('#map-origin').value.trim();
  const destination = 'Ростов-на-Дону, улица Нансена, 104';
  const selectedMode = doc.querySelector('#map-mode').value;
  const mode = ['pd', 'auto', 'mt'].includes(selectedMode) ? selectedMode : 'pd';
  const route = new URL('https://yandex.ru/map-widget/v1/');
  route.searchParams.set('mode', 'routes');
  route.searchParams.set('rtext', origin + '~' + destination);
  route.searchParams.set('rtt', mode);
  route.searchParams.set('lang', 'ru_RU');
  const map = doc.querySelector('#yandex-map');
  map.src = route.href;
  map.title = origin ? 'Маршрут: ' + origin + ' — ' + destination : 'Выбор начала маршрута до ' + destination;
  const external = new URL('https://yandex.ru/maps/');
  external.searchParams.set('rtext', origin + '~' + destination);
  external.searchParams.set('rtt', mode);
  doc.querySelector('#map-route-link').href = external.href;
  doc.querySelector('#map-status').textContent = origin
    ? 'Маршрут от «' + origin + '» до Нансена, 104 передан в Яндекс Карты. Если виджет не загрузился, откройте маршрут по ссылке ниже.'
    : 'Выберите начало маршрута в Яндекс Картах. Если виджет не загрузился, откройте маршрут по ссылке ниже.';
});
doc.documentElement.classList.remove('no-js');
return {  };
